	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("launchcfg: Decode expected 1 row")
		return
	}
